-- Canonical posted material rate authority + BOM consumption.
create or replace function public.rr_material_weighted_rate_canonical_v662(p_material_id uuid,p_data_mode text default 'TEST') returns jsonb language plpgsql stable security definer set search_path to 'public' as $function$
declare m record;r numeric:=0;src text:='NONE';begin select * into m from public.rr_material_master_v805 where id=p_material_id;if not found then raise exception 'Material not found';end if;select p.running_weighted_avg_cost_per_consumption_unit into r from public.rr_material_purchases_v805 p where p.material_id=p_material_id and upper(p.data_mode)=upper(p_data_mode) and coalesce(p.running_weighted_avg_cost_per_consumption_unit,0)>0 order by p.created_at desc limit 1;if coalesce(r,0)>0 then src:='CANONICAL_POSTED_RUNNING_RATE';else select s.weighted_avg_rate_per_consumption_unit into r from public.rr_material_stock_v805 s where s.material_id=p_material_id and upper(s.data_mode)=upper(p_data_mode);src:='LEGACY_STOCK_WEIGHTED_RATE';end if;return jsonb_build_object('material_id',p_material_id,'material_name',m.material_name,'rate_per_consumption_unit',r,'unit',m.consumption_unit,'source',src);end $function$;